{
  "findings": [
    {
      "check_id": "CKV_GCP_50",
      "title": "Workload Identity Pool Provider missing allowed_audiences",
      "resource": "google_iam_workload_identity_pool_provider.pass2",
      "severity": "HIGH",
      "explanation": "The `allowed_audiences` attribute is missing in the `oidc` block. Without specifying allowed audiences, the provider may accept tokens from unintended sources, increasing the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"google_iam_workload_identity_pool_provider\" \"pass2\" {\n  workload_identity_pool_id          = \"example-pool\"\n  workload_identity_pool_provider_id = \"example-provider-2\"\n  attribute_mapping                 = {\n    \"google.subject\"       = \"assertion.sub\"\n  }\n  attribute_condition               = \"assertion.sub == 'repo:myOrg/myRepo:ref:refs/heads/main'\"\n  oidc {\n    issuer_uri                       = \"https://token.actions.githubusercontent.com\"\n    allowed_audiences                = [\"https://github.com/myOrg/myRepo\"]\n  }\n}\n",
  "fix_summary": "Added the `allowed_audiences` attribute to the `oidc` block to restrict token validation to the intended audience, reducing the risk of unauthorized access."
}
